(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["uk"] = {"ui":{"skip":"Перейти до вмісту","back":"← Назад до AI-gile","lang.button":"Мова: {name}","lang.dialog":"Обери мову","lang.search":"Шукати мову","lang.none":"Жодна мова не підходить","lang.notYet":"{name} ще не перекладено","theme.aria":"Перемкнути світлу й темну тему","theme.toLight":"Перемкнути на світлу тему","theme.toDark":"Перемкнути на темну тему","index.title":"AI-gile: твоя ШІ-команда розробників на одній дошці","index.description":"AI-gile — це канбан-дошка для команд, що пишуть код разом зі ШІ. Вони працюють, поки ти спиш, а тобі лишається одна коротка купка: що вирішити, що перевірити і що прийняти.","hero.logoAlt":"Значок дошки AI-gile","hero.h1.html":"Твоя ШІ-команда розробників на одній&nbsp;дошці.","hero.alpha":"🐣 Закрита пре-альфа","hero.alphaTitle":"Рано й недороблено: дякуємо, що пробуєш!","hero.lede":"Вони працюють, поки ти спиш. Зранку на тебе чекає коротка купка: кілька запитань, кілька речей на перевірку, один-два фіолетові діаманти. Клацни, прийми й повертайся до кави.","dl.windows":"Застосунок для Windows","dl.browser":"Запустити в браузері","dl.soon":"Скоро","dl.notify":"🔔 Сповісти, коли відкриється","dl.notifySmall":"Альфа або бета","hero.secondary":"Agile, але команді ніколи не потрібна кава на стендапі. (Стендапи вони все одно проводять.)","pitch.h2":"AI-gile стількома словами, скількома захочеш","pitch.lede":"Обери довжину: від одного слова до 144. Кожна довжина — окремий опис, написаний саме під цей розмір. Тягни повзунок або користуйся стрілками.","pitch.rangeLabel":"Довжина в словах","pitch.dice":"🎲 інший варіант","pitch.words.one":"{n} слово","pitch.words.few":"{n} слова","pitch.words.many":"{n} слів","pitch.words.other":"{n} слова","pitch.letters.one":"{n} літера","pitch.letters.few":"{n} літери","pitch.letters.many":"{n} літер","pitch.letters.other":"{n} літери","pitch.chars.one":"{n} символ","pitch.chars.few":"{n} символи","pitch.chars.many":"{n} символів","pitch.chars.other":"{n} символу","count.line.html.one":"{n} картка на дошці просто зараз","count.line.html.few":"{n} картки на дошці просто зараз","count.line.html.many":"{n} карток на дошці просто зараз","count.line.html.other":"{n} картки на дошці просто зараз","features.aria":"Що він робить","f.pile.h":"Одна купка для тебе","f.pile.html":"<b>Для тебе</b> збирає все, що чекає на тебе в усіх проєктах: запитання, речі на перевірку, завдання, які може зробити лише людина. Твоя черга показує, що далі і скільки це займе.","f.sleep.h":"Команди, що працюють, поки ти спиш","f.sleep.p":"У кожного проєкту є лід і команда ШІ-агентів. Напиши коментар до картки, і команда прокинеться, зробить роботу й поверне її з кроками, які зрозуміє навіть невиспана людина.","f.tester.h":"Спершу перевіряє ШІ-тестувальник","f.tester.p":"Перш ніж щось дійде до тебе, тестувальник проходить кроки в копії застосунку й показує, що побачив, зі скриншотом. Перегляни ті, що пройшли, і прийми одним клацанням.","f.proof.h":"Докази, а не обіцянки","f.proof.p":"Кожна передача показує, що змінилося: файли, різницю, скриншоти. Не треба відкривати кожен застосунок, щоб дізнатися, чи все готово.","f.chat.h":"Спілкуйся зі своїми лідами","f.chat.p":"Бічна панель у стилі Discord: по значку на проєкт, фіолетові діаманти там, де потрібен ти. Напиши ліду ідею, і він перетворить її на картки та план з кнопкою ✅ Почати.","f.tidy.h":"Сам тримає лад","f.tidy.p":"Схожі картки зливаються в одну, заплутані назви виправляються, а перевірка токенів тримає код легким. Менше перемикань і менше думок.","f.private.h":"Твоє, на твоєму комп'ютері","f.private.li1":"Дошка працює на твоїй машині й відповідає лише тобі.","f.private.li2":"Приватні повідомлення між людьми наскрізно зашифровані.","f.private.li3":"Жодних акаунтів, трекерів і кукі.","f.lang.h":"Твоєю мовою","f.lang.p":"Понад 120 мов: від нідерландської, валлійської та японської до піратської, мови Йоди й клінгонської, зі швидким поверненням до англійської для слів розробників.","tl.aria":"Часова шкала від першої розмови до дорожньої карти","tl.h2":"Від першої розмови до того, що далі","tl.lede":"Справжні дати й час, у твоєму часовому поясі. Після сьогодні — це план, без обіцяних дат.","tl.today":"Сьогодні","tl.planned":"заплановано","tl.cards.one":"{n} картка","tl.cards.few":"{n} картки","tl.cards.many":"{n} карток","tl.cards.other":"{n} картки","join.h2":"Долучайся","join.lede":"AI-gile будує одна невелика людина і дуже багато терплячих агентів. Поки що він приватний, у закритій альфі з друзями. Хочеш спробувати, коли він відкриється?","join.btn":"Записати свій інтерес","join.small":"Ми напишемо тобі листа, і більше нічого","footer.tag":"AI-gile. Без трекерів, без кукі, без кави на стендапі.","footer.licence":"Бізнес-ліцензія","footer.status":"Статус","form.sending":"Надсилаємо…","form.failed":"Не вийшло: спробуй пізніше.","form.offline":"Не вдалося зв'язатися з AI-gile: спробуй пізніше.","interest.title":"AI-gile: скажіть мені, коли відкриється альфа","interest.description":"Залиш свою пошту, щоб дізнатися, коли відкриється закрита альфа чи бета AI-gile.","interest.h1":"🔔 Сповісти, коли відкриється","interest.lede":"AI-gile у закритій пре-альфі. Залиш пошту, і ми напишемо один раз, коли для тебе знайдеться місце.","interest.email":"Твоя пошта","interest.which":"Яке тестування?","interest.alpha":"Закрита альфа: рання, сира, багато змін","interest.beta":"Бета: стабільніша, пізніше","interest.both":"Будь-яке, що з'явиться першим","interest.submit":"Додайте мене до списку","interest.thanks":"Дякуємо! Ти в списку.","licence.title":"AI-gile: бізнес-ліцензія","licence.description":"Користуєшся AI-gile у своїй справі? Подай заявку на безкоштовну бізнес-ліцензію.","licence.h1":"📜 Бізнес-ліцензія","licence.lede":"Користуєшся AI-gile на роботі? Розкажи, хто ти й чим займаєшся. Якщо це приносить трохи добра, ліцензія безкоштовна.","licence.company":"Компанія","licence.website":"Вебсайт","licence.what":"Чим ти займаєшся","licence.how":"Чим це допомагає світові","licence.email":"Пошта","licence.submit":"Подати заявку","licence.thanks":"Дякуємо! Ми відповімо на пошту.","status.title":"Статус AI-gile","status.h1":"Статус AI-gile","status.quiet":"Усе тихо","status.checking":"Перевіряємо…","status.offline":"Зараз не вдається зв'язатися зі службою статусу (пробуємо ще)","status.updated":"оновлено {ago}","status.justNow":"щойно","status.min":"{n} хв тому","status.hours":"{n} год тому","status.days":"{n} дн. тому","live.h2":"Дивіться, як це будується, наживо","live.caption":"Кожна картка прихована: ви бачите форму роботи, а не слова.","live.watching.one":"наживо: дивиться {n}","live.watching.other":"наживо: дивляться {n}","live.offline":"Жива дошка трохи перепочиває. Заходьте знову згодом.","live.cols":"Беклог|До виконання|У роботі|Команда перевіряє|Тобі на тест|Для команди|Готово","live.last.now":"Останню картку переміщено щойно","live.last.min.one":"Останню картку переміщено {n} хв тому","live.last.min.other":"Останню картку переміщено {n} хв тому","live.last.hour.one":"Останню картку переміщено {n} год тому","live.last.hour.other":"Останню картку переміщено {n} год тому","live.last.day.one":"Останню картку переміщено {n} дн. тому","live.last.day.other":"Останню картку переміщено {n} дн. тому"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делеговано."]},{"n":2,"texts":["Канбан роботів.","Агенти, впорядковані.","Ідеї збудовано."]},{"n":3,"texts":["Канбан для роботів.","Ідеї стають функціями.","Безкоштовний канбан агентів."]},{"n":5,"texts":["Канбан-дошка, яку ведуть агенти.","Ти пишеш картки. Агенти будують.","Безкоштовно, локально, перевірено, трохи безглуздо."]},{"n":8,"texts":["Безкоштовна канбан-дошка, де замість людей працюють ШІ-агенти.","Напиши ідею. Агенти збудують. Ти приймеш.","Agile для однієї людини й багатьох терплячих роботів."]},{"n":13,"texts":["Канбан-дошка на твоєму комп'ютері, де картки беруть у роботу ШІ-агенти.","Напиши ідею. Команда агентів її збудує, а тестувальник усе перевірить. Ти лише приймаєш.","Безкоштовно, без акаунтів і трекерів: дошка, трохи роботів і ти за головного."]},{"n":21,"texts":["AI-gile — це канбан-дошка для роботи з ШІ-агентами, що пишуть код. Вони беруть картки в роботу, а ти їх перевіряєш і приймаєш.","У кожного проєкту є лід і команда ШІ-агентів. Напиши коментар до будь-якої картки, і команда береться до роботи.","Безкоштовна особиста дошка завдань на твоєму власному комп'ютері. Працюють там роботи, а казати остаточне «так» будеш ти."]},{"n":34,"texts":["Ти кладеш ідеї на дошку. Команда ШІ-агентів перетворює їх на робочі функції, перевіряє й повертає тобі з кроками для спроби. Нічого не вважається готовим, доки ти цього не скажеш.","AI-gile — це саморобна канбан-дошка, яку Rich збудував із великою допомогою агентів, якими вона тепер керує. Вона безкоштовна, працює на твоєму комп'ютері й призначена для друзів, а не на продаж.","Уяви звичайну канбан-дошку з колонками від Беклогу до Готово, тільки картки тут беруть у роботу ШІ-агенти. Вони звітують про хід справи, питають, коли застрягли, і завжди чекають твого схвалення."]},{"n":55,"texts":["AI-gile — це канбан-дошка, де команда складається зі ШІ-агентів. У кожного проєкту є лід, який планує роботу, і помічники, які її виконують. Коли функція готова, ШІ-тестувальник пробує її й робить скриншот, а потім вона потрапляє до твоєї купки. Прийми її або напиши коментар, і вони переробять.","Усе почалося як спосіб однієї людини стежити за багатьма сеансами ШІ-кодування одночасно, а потім виросло в справжню дошку. Вона працює на твоїй машині, не вимагає акаунта й не має трекерів. Безкоштовна для друзів і всіх допитливих. Вона ще й недороблена, тож чекай шорсткостей і зрідка сюрпризів.","Ось чесна версія. Ідеї все одно маєш мати ти, і результати все одно маєш перевіряти ти. А AI-gile робить усе між цим: тримає картки впорядкованими, будить потрібного агента, коли ти коментуєш, показує, що саме змінилося, і збирає все це для тебе в одну коротку купку."]},{"n":89,"texts":["AI-gile — це безкоштовна канбан-дошка, яку ти запускаєш на власному комп'ютері. Замість людей у кожного проєкту є команда ШІ-агентів: лід, що перетворює твої ідеї на картки та план, і помічники, що беруть картки за пріоритетом. Коли щось збудовано, ШІ-тестувальник проходить кроки перевірки й показує тобі, що побачив. Потім усе чекає в одній купці з назвою «Для тебе». Ти приймаєш або коментуєш, і команда пробує ще раз. Без тебе нічого не потрапляє в «Готово».","Є кілька речей, яких ти можеш не чекати. Нічна варта поповнює колонку «До виконання», поки ти спиш, і вибирає картки, яким не потрібна твоя відповідь. Лічильник токенів показує, скільки агенти витратили сьогодні й цього тижня, а режим «Без токенів» велить їм зупинитися. Можна писати друзям, і приватні повідомлення наскрізно зашифровані. Дошка говорить приблизно 120 мовами, зокрема нідерландською, фламандською, піратською та клінгонською. Це не коштує ні копійки, і ніхто не намагається тобі це продати.","AI-gile — невеликий особистий проєкт, а не компанія. Rich хотів доглядати кілька проєктів зі ШІ-кодуванням, не відкриваючи щоразу кожен застосунок, тож разом з агентами збудував для цього дошку, а потім нею ж збудував решту себе. Вона в закритій пре-альфі, тобто здебільшого працює, але лише для жменьки друзів. Немає ні сторінки з цінами, ні розсилки, ні плану зростання. Якщо все це звучить корисно, можеш попроситися спробувати, щойно вона трохи відкриється для інших охочих."]},{"n":144,"texts":["AI-gile — це канбан-дошка для однієї людини й багатьох ШІ-агентів. Вона працює на твоєму власному комп'ютері й повністю безкоштовна. Ти додаєш проєкти, і кожен отримує ліда та невелику команду. Ти спілкуєшся з лідом, трохи як у Discord, і описуєш ідею; лід перетворює її на картки та план, а потім чекає, поки ти натиснеш «Почати». Команда проходить картки за пріоритетом, користуючись простим командним рядком, створеним для мовних моделей. Перш ніж щось повернеться до тебе, ШІ-тестувальник проходить усі кроки в копії застосунку й додає до них скриншот. Готова робота потрапляє до твоєї купки разом зі зміненими файлами та різницею. Ти приймаєш її або залишаєш коментар, і команда прокидається та пробує знову. Лише ти можеш перемістити картку в колонку «Готово».","День з AI-gile, приблизно. Увечері ти залишаєш кілька коментарів: ця кнопка не на місці, той список варто відсортувати, а чи можна додати темну тему. Ти йдеш спати. Агенти читають коментарі, вносять зміни, перевіряють їх і повертають тобі. Якщо «До виконання» порожніє, нічна варта наповнює його з беклогу картками, яким не потрібна твоя відповідь. Зранку на тебе чекає одна коротка купка: кілька запитань і кілька речей на спробу, кожна з кроками, які зрозуміє навіть сонна людина, і зі скриншотом, де все працює. Ти клацаєш, приймаєш добре, а решту відправляєш назад. Лічильник токенів показує, скільки це все з'їло, а режим «Без токенів» є для ощадливих тижнів. Потім ти снідаєш, і в цьому агенти поки що не допоможуть.","Спершу про те, чим AI-gile не є. Це не стартап, не товар на продаж, і ніхто не збирає твої дані. Це безкоштовна дошка, що працює на твоєму комп'ютері, без акаунтів, трекерів і кукі. А є вона єдиним охайним місцем, де видно всі проєкти зі ШІ-кодуванням одразу: команда агентів робить картки, а рішення ухвалюєш ти. Вона зливає схожі картки, виправляє заплутані назви й стежить, наскільки легким лишається код. Вона говорить приблизно 120 мовами, від нідерландської та фламандської до піратської й клінгонської. Друзі можуть писати одне одному приватно й зашифровано. Її збудували Rich і дуже багато терплячих агентів, здебільшого користуючись нею самою. Вона в закритій пре-альфі, тож подекуди шорстка. Якщо звучить цікаво, попроси чемно, і, можливо, потрапиш раніше."]}],"quips":{"1":"Одне слово. Сміливо. Можливо, занадто сміливо.","3":"Три слова. Вже чесніше за більшість сторінок продуктів.","8":"Вісім слів. Усе одно коротше за стендап.","21":"До речі, довжини — це story points. А що ж іще.","55":"П'ятдесят п'ять слів. Поки ти читав, дві картки встигли завершити.","144":"Це найдовший варіант. 233 немає. Агенти пішли спати."}},"timeline":{"first-idea.name":"Перша ідея","first-idea.line":"Найперша розмова, коли коду ще не існувало.","first-board.name":"Перша дошка","first-board.line":"Дошка, що стежить за власною розробкою: картки, колонки, перетягування, проєкти.","team-roles.name":"Команда й ролі","team-roles.line":"Профілі агентів, шаблони команд, простори й хто що робить.","install.name":"Встановлення й релізи","install.line":"Zip, який друг може встановити, самооновлення, канали й відкат.","usage-saver.name":"Заощадження ресурсу","usage-saver.line":"Міряти вартість запусків, тримати код легким, берегти свій ліміт.","friends.name":"Друзі й спільний доступ","friends.line":"Приватні повідомлення, зашифрований ретранслятор, запрошення, ролі й спільні проєкти.","languages.name":"Мови","languages.line":"Кожен екранний текст у мовному файлі, спершу нідерландська й фламандська.","ai-tester.name":"ШІ-тестувальник","ai-tester.line":"Тестувальник першим перевіряє кожну передачу й показує, що побачив.","website.name":"Вебсайт","website.line":"aigile.lol, тизер і ця часова шкала.","streaming.name":"Чат і стримінг","streaming.line":"Discord, Twitch, OBS, режим стримера, GIF-и й емодзі.","no-ai.name":"Версія без ШІ","no-ai.line":"Дошка для тих, хто пише код без ШІ, і публічні дошки.","night-watch.name":"Нічна варта","night-watch.line":"Вартовий і Scrum Master тримають команди в роботі, поки ти спиш.","p-more.name":"Усе інше","p-more.line":"Менші ідеї, що чекають своєї черги.","p-android.name":"Телефон і Android","p-android.line":"Доступ до дошки з телефона, а потім рідний застосунок для Android.","p-release.name":"Альфа й далі","p-release.line":"Закрита альфа, жива сторінка, потім бета.","p-languages.name":"Більше мов","p-languages.line":"Понад сотня мов і режим занурення для тих, хто вчить мову.","p-engines.name":"Більше ШІ-рушіїв","p-engines.line":"Обирай Claude, Codex або Gemini для кожного агента.","p-pro.name":"Професійна практика","p-pro.line":"Мітки ризику, ворота злиття, картки інцидентів і запобіжники.","p-self.name":"Турбота про тебе","p-self.line":"Режим втоми, нагадування про догляд за собою і 4:20.","p-servers.name":"Сервери й масштаб","p-servers.line":"Глобальні налаштування сервера, ролі й планування зростання.","p-livestream.name":"Додатки для стримінгу","p-livestream.line":"Чат Twitch, власні емодзі й публічний перегляд наживо."},"words":{"button":"📖 Слова розробників","h":"📖 Пояснення слів розробників","intro":"Слова, які використовують розробники (і ШІ-команди), простою мовою.","search":"Шукати слово…","none":"Такого слова немає.","close":"Закрити","list":[{"id":"backlog","word":"Беклог","text":"Ідеї й робота, яку ще не заплановано. Над ними ніхто не працює, доки картка не перейде в «До виконання»."},{"id":"sprint","word":"Спринт","text":"Короткий відрізок роботи (часто тиждень-два) із чітко узгодженим набором карток, які треба закінчити.","also":["спринти","спринтів","спринту","sprint","sprints"]},{"id":"standup","word":"Стендап","text":"Швидка зустріч: що зробив кожен учасник команди, що робить далі і що йому заважає.","also":["стендапи","стендапу","standup","stand-up","stand-ups"]},{"id":"bug","word":"Баг","text":"Щось, що не працює так, як має.","also":["баги","бага","багів","bug","bugs"]},{"id":"test","word":"Тест","text":"Перевірка готової роботи, щоб переконатися, що вона робить те, що просили, перш ніж ти її приймеш.","also":["тести","тесту","тестів","тестування","тестувати","test","tests"],"noTip":1},{"id":"commit","word":"Коміт","text":"Збережений знімок коду з короткою приміткою про те, що змінилося. До нього завжди можна повернутися.","also":["коміти","комітів","commit","commits"]},{"id":"push","word":"Пуш","text":"Надсилання збережених знімків (комітів) з цього комп'ютера на GitHub, щоб вони були збережені й доступні іншим."},{"id":"branch","word":"Гілка","text":"Окрема лінія роботи в коді, щоб можна було вносити зміни, не чіпаючи основну версію.","also":["гілки","branch","branches"]},{"id":"merge","word":"Мерж","text":"Злиття змін гілки назад в основну версію."},{"id":"repo","word":"Репозиторій","text":"Папка проєкту з кодом і повною історією комітів, зазвичай також збережена на GitHub.","also":["репо","repo","repository"]},{"id":"refactor","word":"Рефакторинг","text":"Наведення ладу в коді без зміни того, що він робить: менші файли, зрозуміліші назви, менше повторів."},{"id":"deploy","word":"Деплой","text":"Розгортання нової версії, наприклад на сервері, де нею користуються люди."},{"id":"kanban","word":"Канбан","text":"Дошка зі стовпцями (До виконання, У роботі, Готово), де картки рухаються зліва направо в міру роботи."},{"id":"wip","word":"WIP-ліміт","text":"Work in progress: максимум карток, які має вміщати стовпець, щоб команда закінчувала справи, перш ніж братися за нові.","also":["WIP","ліміт WIP"]},{"id":"pr","word":"Пул-реквест","text":"Прохання перевірити зміни гілки й злити їх в основну версію.","also":["PR","pull request"]},{"id":"hook","word":"Хук","text":"Маленька команда, яка сама запускається в певний момент, напр. коли стартує сесія ШІ, щоб команда чула твої коментарі.","also":["хуки","hook","hooks"]},{"id":"token","word":"Токен","text":"Одиниця, у якій рахується використання ШІ: приблизно кілька літер тексту, прочитаних або написаних. Менше токенів - більше тарифу лишається.","also":["токени","токенів","token","tokens"]},{"id":"agent","word":"Агент","text":"ШІ, що самостійно працює над завданням: читає код, вносить зміни, запускає перевірки і звітує.","also":["агенти","агентів","agent","agents"]}]}};
